const op=new YankinOperation();const money=n=>(n/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const $=s=>document.querySelector(s);const amount=v=>{if(!/^\d+(?:[.,]\d{1,2})?$/.test(v.trim()))throw Error('Informe um valor positivo, com até duas casas decimais');return Math.round(Number(v.replace(',','.'))*100);};function act(f){try{f();$('#feedback').textContent='Exemplo atualizado. Nenhum valor real foi movimentado.';}catch(e){$('#feedback').textContent=e.message;}render();}function render(){
$('#rooms').innerHTML=Object.entries(op.rooms).map(([r,s])=>`<div class="room"><b>Sala ${r}</b><p>${s}</p>${s==='Em limpeza'?`<button data-clean="${r}">Confirmar limpeza e liberar</button>`:''}</div>`).join('');
$('#active').innerHTML=op.accounts.filter(a=>a.active).map(a=>`<article><h3>Comanda ${a.id} · Profissional ${a.person} · Sala ${a.room}</h3><p>${a.minutes} minutos · término previsto ${new Date(a.started+a.minutes*60000).toLocaleTimeString('pt-BR')} · total ${money(op.total(a))}</p><p>${Date.now()>=a.started+a.minutes*60000?'Tempo encerrado: conferir consumo e encaminhar ao caixa.':'Atendimento em andamento.'}</p><button data-bar="${a.id}" data-item="Água">Água + R$ 8</button><button data-bar="${a.id}" data-item="Suco">Suco + R$ 12</button><button data-finish="${a.id}">Encerrar e encaminhar ao caixa</button></article>`).join('');
$('#pending').innerHTML=op.accounts.filter(a=>!a.active).map(a=>`<article><h3>Comanda ${a.id} · Cliente exemplo ${a.id} · Profissional ${a.person}</h3><p>Serviço ${money(a.service)} · Bar ${money(op.total(a)-a.service)} · Total ${money(op.total(a))}</p><p>Consumo: ${a.bar.map(i=>i.item+' '+money(i.price)).join(', ')||'nenhum'}</p><p>${a.payments.map(p=>p.method+': '+money(p.amount)).join(' / ')||'Sem pagamento'} · Saldo ${money(op.due(a))}</p>${op.due(a)?`<form data-pay="${a.id}"><label>Forma<select name="method"><option>Pix</option><option>Débito</option><option>Crédito</option><option>Dinheiro</option></select></label><label>Valor<input name="amount" inputmode="decimal" required aria-label="Valor do pagamento"></label><button>Registrar pagamento de exemplo</button></form>`:'<b>Quitado · cliente liberado · comissão no relatório</b>'}</article>`).join('')||'<p>Nenhuma comanda aguardando pagamento.</p>';
$('#commissions').innerHTML=['A','B'].map(p=>`<article><h3>Profissional ${p}</h3><p>Apurado ${money(op.accounts.filter(a=>a.person===p&&!a.active).reduce((s,a)=>s+a.commission,0))} · Saldo liberado ${money(op.balance(p))}</p><p>Repasses: ${op.payouts.filter(x=>x.person===p).map(x=>x.method+' '+money(x.amount)).join(' / ')||'nenhum'}</p><form data-payout="${p}"><label>Forma<select name="method"><option>Dinheiro</option><option>Pix</option></select></label><label>Valor<input name="amount" inputmode="decimal" required aria-label="Valor do repasse"></label><button>Registrar repasse de exemplo</button></form></article>`).join('');
const payments=op.accounts.flatMap(a=>a.payments);$('#summary').innerHTML=`<p>Atendimentos encerrados: ${op.accounts.filter(a=>!a.active).length} · Recebido ${money(payments.reduce((s,p)=>s+p.amount,0))} · Pendente ${money(op.accounts.filter(a=>!a.active).reduce((s,a)=>s+op.due(a),0))}</p>`+['Pix','Débito','Crédito','Dinheiro'].map(m=>`<p>${m}: ${money(payments.filter(p=>p.method===m).reduce((s,p)=>s+p.amount,0))}</p>`).join('')+`<p>Comissões pagas ${money(op.payouts.reduce((s,p)=>s+p.amount,0))} · Saldo liberado acumulado ${money(op.balance('A')+op.balance('B'))}</p>`;
}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.clean)act(()=>op.clean(b.dataset.clean));if(b.dataset.bar)act(()=>op.addBar(Number(b.dataset.bar),b.dataset.item));if(b.dataset.finish)act(()=>op.finish(Number(b.dataset.finish)));});document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(f.id==='start')act(()=>op.start($('#room').value,$('#professional').value,Number($('#minutes').value)));if(f.dataset.pay)act(()=>op.pay(Number(f.dataset.pay),f.elements.method.value,amount(f.elements.amount.value)));if(f.dataset.payout)act(()=>op.payout(f.dataset.payout,f.elements.method.value,amount(f.elements.amount.value)));});$('#print').onclick=()=>window.print();render();setInterval(()=>{if(!['INPUT','SELECT'].includes(document.activeElement?.tagName))render();},60000);
